import { ref, reactive, computed, watch } from 'vue'
import type { AnalysisPayload } from '../../types/physics'
import { useRcCircuitLayout } from './useRcCircuitLayout'
import { useRcCircuitTrials } from './useRcCircuitTrials'
import { timeConstant, chargingVoltage, dischargingVoltage } from './useRcCircuitCalculations'

export function useRcCircuitExperiment() {
  const params = reactive({
    R: 1000,    // ohm
    C: 0.001,   // F (1000 μF)
    V0: 10,     // V
    mode: 'charge' as 'charge' | 'discharge',
  })

  watch(() => params.R, (v) => { params.R = Math.max(100, Math.min(10000, Math.round(v / 100) * 100)) })
  watch(() => params.C, (v) => { params.C = Math.max(0.0001, Math.min(0.01, Math.round(v * 10000) / 10000)) })
  watch(() => params.V0, (v) => { params.V0 = Math.max(1, Math.min(20, Math.round(v))) })

  const running = ref(false)
  const paused = ref(false)
  const simTime = ref(0)
  const phase = ref<'ready' | 'running' | 'done'>('ready')

  const tau = computed(() => timeConstant(params.R, params.C))
  const currentV = computed(() => {
    if (phase.value === 'ready') return params.mode === 'charge' ? 0 : params.V0
    if (params.mode === 'charge') return chargingVoltage(params.V0, simTime.value, tau.value)
    return dischargingVoltage(params.V0, simTime.value, tau.value)
  })

  function updateSim(dt: number) {
    if (!running.value || paused.value) return
    simTime.value += dt
    phase.value = 'running'
    if (simTime.value > 5 * tau.value) {
      phase.value = 'done'
      simTime.value = 5 * tau.value
    }
  }

  function togglePause() {
    if (!running.value) {
      running.value = true; paused.value = false; simTime.value = 0
      phase.value = 'running'
    } else { paused.value = !paused.value }
  }
  function resetSim() {
    running.value = false; paused.value = false; simTime.value = 0; phase.value = 'ready'
  }

  const layout = useRcCircuitLayout()
  const trials = useRcCircuitTrials(
    { get value() { return { R: params.R, C: params.C, tau: tau.value, t: simTime.value, V: currentV.value, mode: params.mode } } }
  )

  function exportToAnalysis() {
    if (trials.trials.value.length < 2) return
    const payload: AnalysisPayload = {
      sourceExperiment: 'rc-circuit', sourceNameAr: 'دائرة RC',
      readings: trials.trials.value.map(t => ({ R: t.R, C: t.C, tau: t.tau, t: t.t, V: t.V })),
      columns: [
        { key: 'R', label: 'R (Ω)', unit: 'Ω' },
        { key: 'C', label: 'C (F)', unit: 'F' },
        { key: 'tau', label: 'τ (s)', unit: 's' },
        { key: 't', label: 't (s)', unit: 's' },
        { key: 'V', label: 'V (V)', unit: 'V' },
      ],
      equations: [
        { name: 'RC Time Constant', formula: 'τ = R × C', variables: [{ symbol: 'τ', label: 'Time constant' }, { symbol: 'R', label: 'Resistance' }, { symbol: 'C', label: 'Capacitance' }], solveFor: ['tau'] },
        { name: 'Charging', formula: 'V = V₀(1 - e^(-t/τ))', variables: [{ symbol: 'V', label: 'Voltage' }, { symbol: 'V₀', label: 'Source voltage' }, { symbol: 't', label: 'Time' }, { symbol: 'τ', label: 'Time constant' }], solveFor: ['V'] },
      ],
      suggestedPlots: [{ xKey: 't', yKey: 'V', xLabel: 't (s)', yLabel: 'V (V)', type: 'line' }],
    }
    localStorage.setItem('analysis_payload', JSON.stringify(payload))
    window.open('/analysis', '_blank')
  }
  function handleDrop(fromId: string, x?: number, y?: number) {
    if (x === undefined || y === undefined) return
    const el = document.elementFromPoint(x, y)
    const toPanel = el?.closest('.draggable-panel')
    const toId = toPanel?.getAttribute('data-id')
    if (!toId || fromId === toId) return
    for (const col of Object.keys(layout.columnMap)) {
      const arr = layout.columnMap[col]
      const fi = arr.indexOf(fromId), ti = arr.indexOf(toId)
      if (fi >= 0 && ti >= 0) { const t = arr[fi]; arr[fi] = arr[ti]; arr[ti] = t }
    }
  }
  function onResizeStart(col: string, e: MouseEvent) {
    if (!(col in layout.widths)) return
    const startX = e.clientX, startW = (layout.widths as Record<string, number>)[col] as number
    function move(ev: MouseEvent) { (layout.widths as Record<string, number>)[col] = Math.max(220, startW + (ev.clientX - startX)) }
    function up() { window.removeEventListener('mousemove', move); window.removeEventListener('mouseup', up) }
    window.addEventListener('mousemove', move); window.addEventListener('mouseup', up)
  }

  const lab = { running, paused, simTime, phase, tau, currentV, togglePause, updateSim }
  return { params, lab, layout, trials, resetSim, exportToAnalysis, onResizeStart, handleDrop }
}

